92	static size_t mjpeg_input(JDEC *jd, uint8_t *buff, size_t nbyte)
93	{
94	  struct mjpeg_iodev_s *io = (struct mjpeg_iodev_s *)jd->device;
95	  size_t avail = io->len - io->pos;
96	  if (nbyte > avail) nbyte = avail;
97	  if (buff) memcpy(buff, io->data + io->pos, nbyte);
98	  io->pos += nbyte;
99	  return nbyte;
100	}
