252	static void overlay_result(int8_t person_score, int detected)
253	{
254	  uint16_t bg = detected ? ((0 << 11) | (40 << 5) | 0)    /* green */
255	                         : ((20 << 11) | (0 << 5) | 0);   /* red */
256	  uint16_t fg = 0xFFFF;
257	  const char *label = detected ? "PERSON" : "NO PERSON";
258	
259	  draw_filled_rect(0, 0, TEST_WIDTH - 1, (FONT_H + 4) * FONT_SCALE, bg);
260	  draw_string(4, 2, label, fg, FONT_SCALE);
261	
262	  char s[16];
263	  snprintf(s, sizeof(s), "P:%d", person_score);
264	  draw_string(TEST_WIDTH - (FONT_W + 1) * FONT_SCALE * 6, 2, s, fg,
265	              FONT_SCALE);
266	}
