294	static void fb_blit(uint32_t w, uint32_t h)
295	{
296	  struct lcddev_area_s area;
297	  memset(&area, 0, sizeof(area));
298	  area.row_start = 0;
299	  area.row_end   = h - 1;
300	  area.col_start = 0;
301	  area.col_end   = w - 1;
302	  area.stride    = w * 2;
303	  area.data      = (FAR uint8_t *)g_rgbbuf;
304	  ioctl(g_fbfd, LCDDEVIO_PUTAREA, (uintptr_t)&area);
305	}
