307	/****************************************************************************
308	 * BMP Loader
309	 ****************************************************************************/
310	
311	static int load_bmp_grayscale(const char *filepath, int8_t *image_data)
312	{
313	  uint8_t header[BMP_HEADER_SIZE];
314	  uint8_t pixel;
315	  int fd = open(filepath, O_RDONLY);
316	  if (fd < 0) { printf("ERROR: open %s: %d\n", filepath, errno); return -errno; }
317	  if (read(fd, header, BMP_HEADER_SIZE) != BMP_HEADER_SIZE) { close(fd); return -EIO; }
318	  if (header[0] != 'B' || header[1] != 'M') { close(fd); return -EINVAL; }
319	  for (int i = 0; i < NUM_ROWS * NUM_COLS; i++)
320	    {
321	      if (read(fd, &pixel, 1) != 1) { close(fd); return -EIO; }
322	      int row = i / NUM_COLS, col = i % NUM_COLS;
323	      image_data[(NUM_ROWS - 1 - row) * NUM_COLS + col] =
324	          static_cast<int8_t>(static_cast<int>(pixel) - 128);
325	    }
326	  close(fd);
327	  return 0;
328	}
