/* Decode all 896 anchors -> candidate detections above SCORE_THRESH.
 * box_t  : regressor tensor data (INT8), layout [896][16]
 * score_t: classificator tensor data (INT8), layout [896][1]
 * reverse_output_order=true => raw box is [xc, yc, w, h].
 */

static int decode_detections(const int8_t *box_t, float box_scale, int box_zp,
                             const int8_t *score_t, float score_scale,
                             int score_zp)
{
  int n = 0;

  for (int i = 0; i < NUM_ANCHORS && n < MAX_CAND; i++)
    {
      float raw_score = dequant(score_t, i, score_scale, score_zp);
      float score = sigmoidf(raw_score);
      if (score < SCORE_THRESH)
        continue;

      const int base = i * NUM_COORDS;
      float acx = g_anchor_cx[i];
      float acy = g_anchor_cy[i];

      float xc = dequant(box_t, base + 0, box_scale, box_zp) / BOX_SCALE + acx;
      float yc = dequant(box_t, base + 1, box_scale, box_zp) / BOX_SCALE + acy;
      float w  = dequant(box_t, base + 2, box_scale, box_zp) / BOX_SCALE;
      float h  = dequant(box_t, base + 3, box_scale, box_zp) / BOX_SCALE;

      detection_s *d = &g_cand[n++];
      d->score = score;
      d->xmin = xc - w * 0.5f;
      d->ymin = yc - h * 0.5f;
      d->xmax = xc + w * 0.5f;
      d->ymax = yc + h * 0.5f;
      d->frontal = 0;

      for (int k = 0; k < NUM_KP; k++)
        {
          int off = base + 4 + k * 2;
          d->kp[k][0] =
            dequant(box_t, off + 0, box_scale, box_zp) / BOX_SCALE + acx;
          d->kp[k][1] =
            dequant(box_t, off + 1, box_scale, box_zp) / BOX_SCALE + acy;
        }
    }

  return n;
}

